#include "game.hpp"
#include <algorithm>
#include <iostream>
#include <string>
namespace echodrive {
Game::Game():settings_(loadSettings("echodrive.cfg")),voice_(settings_.language){audio_.setListener({0,0,0},0);}
void Game::menu()const{std::cout<<"\n=== EchoDrive 0.2 | Ahmed Samy Studio ===\n1 تقدم | 2 فرامل | 3 يمين | 4 يسار | 5 أسرع | 6 أبطئ\na قيادة آلية | m قيادة يدوية | r إعادة | s الحالة | l الشوارع | v السيارات | q خروج\n> ";}
void Game::selectStreet(){std::cout<<"اختر شارعًا من 1 إلى 15: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>15)n=1;settings_.street=n;const auto&x=allStreets()[n-1];voice_.announce("بدأت "+x.ar+" من دولة "+x.country+". "+x.description,"Starting "+x.en+" in "+x.country+". "+x.description);}
void Game::selectVehicle(){std::cout<<"اختر سيارة من 1 إلى 25: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>25)n=1;vehicle_=n;const auto&x=allVehicles()[n-1];voice_.announce("اخترت "+x.ar+"، السرعة القصوى "+std::to_string(x.topSpeed),"Selected "+x.en+", top speed "+std::to_string(x.topSpeed));}
Command Game::parse(const std::string&r)const{if(r=="1"||r=="w"||r=="تقدم")return Command::Forward;if(r=="2"||r=="توقف"||r=="فرامل")return Command::Brake;if(r=="3"||r=="right"||r=="يمين")return Command::Right;if(r=="4"||r=="left"||r=="يسار")return Command::Left;if(r=="5"||r=="أسرع")return Command::Faster;if(r=="6"||r=="أبطئ")return Command::Slower;if(r=="a"||r=="قيادة آلية")return Command::Auto;if(r=="m"||r=="قيادة يدوية")return Command::Manual;if(r=="r"||r=="إعادة")return Command::Reset;if(r=="s")return Command::Repeat;if(r=="l")return Command::ListStreets;if(r=="v")return Command::ListVehicles;if(r=="q"||r=="خروج")return Command::Quit;return Command::Unknown;}
void Game::status()const{std::string d=heading_<0?"يسار":heading_>0?"يمين":"مستقيم";std::string e=heading_<0?"left":heading_>0?"right":"straight";const auto&car=allVehicles()[vehicle_-1];voice_.announce("السرعة "+std::to_string((int)speed_)+" كيلومتر، الاتجاه "+d+"، السيارة "+car.ar,"Speed "+std::to_string((int)speed_)+" kilometers per hour, direction "+e+", vehicle "+car.en);}
void Game::listContent()const{std::cout<<"\n--- 15 Streets ---\n";for(const auto&s:allStreets())std::cout<<s.id<<". "<<s.en<<" — "<<s.country<<"\n";std::cout<<"\n--- 25 Vehicles ---\n";for(const auto&v:allVehicles())std::cout<<v.id<<". "<<v.en<<" ["<<v.category<<"] max "<<v.topSpeed<<" km/h\n";}
void Game::handle(Command c){switch(c){case Command::Forward:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+8);voice_.announce("تقدم","Moving forward");break;case Command::Brake:speed_=std::max(0.0,speed_-20);voice_.announce("فرامل","Braking");break;case Command::Right:heading_=1;audio_.setListener({0,0,0},0.25);voice_.announce("يمين، الصوت الآن من الجهة اليمنى","Turning right, audio cue on the right");break;case Command::Left:heading_=-1;audio_.setListener({0,0,0},-0.25);voice_.announce("يسار، الصوت الآن من الجهة اليسرى","Turning left, audio cue on the left");break;case Command::Faster:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+15);status();break;case Command::Slower:speed_=std::max(0.0,speed_-15);status();break;case Command::Auto:settings_.automaticDriving=true;voice_.announce("تم تشغيل القيادة الآلية","Automatic driving enabled");break;case Command::Manual:settings_.automaticDriving=false;voice_.announce("تم تشغيل القيادة اليدوية","Manual driving enabled");break;case Command::Reset:speed_=0;heading_=0;audio_.setListener({0,0,0},0);voice_.announce("أعيدت الرحلة","Trip reset");break;case Command::Repeat:status();break;case Command::ListStreets:case Command::ListVehicles:listContent();break;case Command::Quit:saveSettings(settings_,"echodrive.cfg");voice_.announce("إلى اللقاء","Goodbye");break;case Command::Unknown:voice_.announce("لم أفهم الأمر","Command not understood");}}
void Game::run(){voice_.announce("مرحبًا بك في EchoDrive. الإصدار الموسع بالصوت المكاني.","Welcome to EchoDrive. Spatial audio edition.");selectStreet();selectVehicle();for(;;){menu();std::string x;if(!std::getline(std::cin,x))break;Command c=parse(x);handle(c);if(c==Command::Quit)break;}}
}
